const context =
  $('Build Platform Report Stats').item.json;

let text =
  $json.text ||
  $json.message?.content ||
  $json.output?.[0]?.content?.[0]?.text ||
  $json.content?.find(
    item => item.type === 'output_text'
  )?.text ||
  '';

if (typeof text !== 'string') {
  text = JSON.stringify(text);
}

text = text
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

if (!text) {
  throw new Error(
    'لم يتم العثور على محتوى التقرير'
  );
}

let report;

try {
  report = JSON.parse(text);
} catch (error) {
  throw new Error(
    'تقرير المنصة ليس JSON صالحًا'
  );
}

if (
  !report ||
  typeof report !== 'object' ||
  Array.isArray(report)
) {
  throw new Error(
    'نتيجة التقرير يجب أن تكون JSON Object'
  );
}

return {
  json: {
    report_id: context.report_id,
    report_generation: context.report_generation,
    client_id: context.client_id,
    client_name: context.client_name || null,

    branch_id: context.branch_id ?? null,
    branch_name: context.branch_name || null,

    platform_id: context.platform_id,
    platform_name: context.platform_name,

    report_scope: context.report_scope,
    report_type: context.report_type,

    period_start: context.period_start,
    period_end: context.period_end,

    total_feedback:
      context.stats?.total_feedback || 0,

    stats: context.stats || {},

    report_title:
      report.report_title || null,

    executive_summary:
      report.executive_summary || null,

    sentiment_summary:
      report.sentiment_summary || {},

    top_strengths: Array.isArray(
      report.top_strengths
    )
      ? report.top_strengths
      : [],

    top_issues: Array.isArray(
      report.top_issues
    )
      ? report.top_issues
      : [],

    urgent_cases_summary:
      report.urgent_cases_summary || {
        count: 0,
        summary: ''
      },

    customer_needs: Array.isArray(
      report.customer_needs
    )
      ? report.customer_needs
      : [],

    sales_opportunities: Array.isArray(
      report.sales_opportunities
    )
      ? report.sales_opportunities
      : [],

    recommendations: Array.isArray(
      report.recommendations
    )
      ? report.recommendations
      : [],

    action_plan: Array.isArray(
      report.action_plan
    )
      ? report.action_plan
      : [],

    conclusion:
      report.conclusion || null,

    report_data: report,

    generated_at:
      new Date().toISOString()
  }
};

const client = $json;
if (!Number.isSafeInteger(Number(client.id)) || Number(client.id) <= 0) throw new Error('INVALID_REPORT_CLIENT');
const initial = !client.initial_report_generated_at;
// Never derive an idempotency key from the current execution's clock.
// Each initial platform window is finalized from its immutable link timestamp below.
const end = client.next_report_at || client.activated_at || client.created_at;
const start = initial ? new Date(Date.parse(end) - 30 * 86400000).toISOString()
  : client.last_report_at || client.activated_at || client.created_at;
if (!Number.isFinite(Date.parse(start)) || !Number.isFinite(Date.parse(end)) || Date.parse(start) > Date.parse(end)) throw new Error('INVALID_REPORT_PERIOD');
return { json: { ...client, report_type: initial ? 'initial_historical' : 'weekly', period_start: new Date(start).toISOString(), period_end: new Date(end).toISOString() } };

const context =
  $('Restore Reserved Context').last().json;

// إزالة العنصر الفارغ إن وجد
const feedback = $input.all()
  .map(item => item.json)
  .filter(item => item.source_record_id);


if (feedback.some(row => Number(row.client_id) !== Number(context.client_id) || Number(row.platform_id) !== Number(context.id) || (row.branch_id ?? null) !== (context.branch_id ?? null))) throw new Error('REPORT_FEEDBACK_SCOPE_MISMATCH');

const total = feedback.length;

const percent = value =>
  total > 0
    ? Number(((value / total) * 100).toFixed(2))
    : 0;

const sentimentCounts = {
  positive: 0,
  negative: 0,
  neutral: 0
};

const severityCounts = {
  low: 0,
  medium: 0,
  high: 0
};

const categoryCounts = {};
const negativeCategoryCounts = {};
const positiveCategoryCounts = {};

let needsReplyCount = 0;
let complaintsCount = 0;
let salesOpportunitiesCount = 0;

const ratings = [];

const normalizeCategories = value => {
  if (Array.isArray(value)) {
    return value;
  }

  if (!value) {
    return ['أخرى'];
  }

  return [String(value)];
};

for (const row of feedback) {
  const sentiment = [
    'positive',
    'negative',
    'neutral'
  ].includes(row.sentiment)
    ? row.sentiment
    : 'neutral';

  sentimentCounts[sentiment]++;

  const severity = [
    'low',
    'medium',
    'high'
  ].includes(row.severity)
    ? row.severity
    : 'low';

  severityCounts[severity]++;

  if (row.needs_reply === true) {
    needsReplyCount++;
  }

  if (row.is_complaint === true) {
    complaintsCount++;
  }

  if (row.is_sales_opportunity === true) {
    salesOpportunitiesCount++;
  }

  const rating = Number(row.rating);

  if (
    row.rating !== null &&
    row.rating !== undefined &&
    !Number.isNaN(rating)
  ) {
    ratings.push(rating);
  }

  const categories = normalizeCategories(
    row.category
  );

  for (const category of categories) {
    const name = String(category || 'أخرى');

    categoryCounts[name] =
      (categoryCounts[name] || 0) + 1;

    if (sentiment === 'negative') {
      negativeCategoryCounts[name] =
        (negativeCategoryCounts[name] || 0) + 1;
    }

    if (sentiment === 'positive') {
      positiveCategoryCounts[name] =
        (positiveCategoryCounts[name] || 0) + 1;
    }
  }
}

const sortCounts = counts =>
  Object.entries(counts)
    .sort((a, b) => b[1] - a[1])
    .map(([name, count]) => ({
      name,
      count
    }));

const averageRating = ratings.length
  ? Number(
      (
        ratings.reduce(
          (sum, value) => sum + value,
          0
        ) / ratings.length
      ).toFixed(2)
    )
  : null;

const urgentCases = feedback
  .filter(row =>
    ['high', 'critical'].includes(row.severity) && (row.sentiment === 'negative' || row.is_complaint === true)
  )
  .map(row => ({
    source_record_id: row.source_record_id,
    source_table: row.source_table,
    client_id: row.client_id,
    platform_id: row.platform_id,
    branch_id: row.branch_id ?? null,
    severity: row.severity,
    sentiment: row.sentiment,
    is_complaint: row.is_complaint === true,
    external_id: row.external_id || null,
    feedback_text: row.feedback_text || '',
    category: normalizeCategories(row.category),
    reason: row.reason || null,
    suggested_reply:
      row.suggested_reply || null,
    published_at: row.published_at || null
  }));

const feedbackForAi = feedback.map(row => ({
  source_record_id: row.source_record_id,
  feedback_text: row.feedback_text || '',
  rating: row.rating ?? null,
  sentiment: row.sentiment || 'neutral',
  category: normalizeCategories(row.category),
  severity: row.severity || 'low',
  needs_reply: row.needs_reply === true,
  is_complaint: row.is_complaint === true,
  is_sales_opportunity:
    row.is_sales_opportunity === true,
  reason: row.reason || null,
  published_at: row.published_at || null
}));

return [
  {
    json: {
      report_id: context.report_id,
      report_generation: context.report_generation,
      client_id: context.client_id,
      client_name: context.client_name || null,

      branch_id: context.branch_id ?? null,
      branch_name: context.branch_name || null,

      platform_id: context.id,
      platform_name: context.platform_name,

      report_scope: context.report_scope,
      report_type: context.report_type,

      period_start: context.period_start,
      period_end: context.period_end,

      stats: {
        report_generation: context.report_generation,
        total_feedback: total,

        sentiment: {
          positive: sentimentCounts.positive,
          negative: sentimentCounts.negative,
          neutral: sentimentCounts.neutral,

          positive_percentage:
            percent(sentimentCounts.positive),

          negative_percentage:
            percent(sentimentCounts.negative),

          neutral_percentage:
            percent(sentimentCounts.neutral)
        },

        severity: severityCounts,

        average_rating: averageRating,

        needs_reply_count:
          needsReplyCount,

        complaints_count:
          complaintsCount,

        sales_opportunities_count:
          salesOpportunitiesCount,

        categories:
          sortCounts(categoryCounts),

        top_issues:
          sortCounts(
            negativeCategoryCounts
          ).slice(0, 5),

        top_strengths:
          sortCounts(
            positiveCategoryCounts
          ).slice(0, 5),

        reputation_urgent_cases: urgentCases,

        urgent_cases_count:
          urgentCases.length
      },

      urgent_cases: urgentCases,
      feedback_for_ai: feedbackForAi
    }
  }
];

const client = $('Determine Report Period').last().json;
return $input.all().map(({ json: platform }) => {
  const branch = Array.isArray(platform.branches) ? platform.branches[0] : platform.branches;
  if (Number(platform.client_id) !== Number(client.id) || !Number.isSafeInteger(Number(platform.id)) || Number(platform.id) <= 0 ||
      (platform.branch_id != null && (!branch || Number(branch.id) !== Number(platform.branch_id) || Number(branch.client_id) !== Number(client.id)))) throw new Error('REPORT_PLATFORM_SCOPE_MISMATCH');
  let start = client.period_start, end = client.period_end;
  {
    // First report covers the 30 days before this link was added. Retries and
    // repeated completion RPCs cannot move the window, even across midnight.
    const linked = String(platform.created_at || '');
    const timestamp = /(?:Z|[+-]\d{2}(?::?\d{2})?)$/i.test(linked) ? linked : linked + 'Z';
    const anchor = Date.parse(timestamp);
    if (!Number.isFinite(anchor) || anchor > Date.now()) throw new Error('INVALID_PLATFORM_REPORT_ANCHOR');
    platform.link_report_end = new Date(anchor).toISOString();
    platform.link_report_start = new Date(anchor - 30 * 86400000).toISOString();
    if (client.report_type === 'initial_historical') { end=platform.link_report_end; start=platform.link_report_start; }
  }
  const legacyScope = platform.branch_id != null ? `${platform.platform_name}:branch:${platform.branch_id}` : `${platform.platform_name}:client`;
  return { json: { ...platform, client_name: client.name || null, branch_name: branch?.name || null,
    report_type: client.report_type, period_start: start, period_end: end,
    base_report_scope: `${legacyScope}:platform:${platform.id}`, legacy_report_scope: legacyScope, report_scope: `${legacyScope}:platform:${platform.id}` } };
});

const trigger = $('Resolve Report Trigger').last().json || {};
return $input.all().filter(({ json: client }) => {
  const now = Date.now();
  const eligible = client.subscription_status === 'trial'
    ? Boolean(client.trial_ends_at) && Date.parse(client.trial_ends_at) > now
    : client.subscription_status === 'active' && (!client.current_period_end || Date.parse(client.current_period_end) > now);
  if (!eligible || (trigger.targeted && Number(client.id) !== Number(trigger.client_id))) return false;
  const platforms = Array.isArray(client.client_platforms) ? client.client_platforms.filter(p => p.is_active === true) : [];
  if (!platforms.length || (trigger.platform_id && !platforms.some(p => Number(p.id) === Number(trigger.platform_id)))) return false;
  const initial = !client.initial_report_generated_at;
  const dueAt = Date.parse(client.next_report_at || '');
  if (!initial && (!Number.isFinite(dueAt) || dueAt > now)) return false;
  return platforms.every(platform => {
    const completedAt = Date.parse(platform.last_success_at || '');
    return platform.connection_status === 'connected' && Number.isFinite(completedAt) && (initial || completedAt >= dueAt);
  });
});

const raw = $input.all()[0]?.json || {};
const input = raw.body && typeof raw.body === 'object' ? raw.body : raw;
if (input.client_id !== undefined || input.platform_id !== undefined || input.source === 'platform_sync_completed') {
  const clientId = Number(input.client_id);
  const platformId = input.platform_id == null ? null : Number(input.platform_id);
  if (!Number.isSafeInteger(clientId) || clientId <= 0 ||
      (platformId !== null && (!Number.isSafeInteger(platformId) || platformId <= 0)) ||
      (input.source === 'platform_sync_completed' && platformId === null)) throw new Error('INVALID_REPORT_SCOPE');
  return [{ json: { client_id: clientId, platform_id: platformId, targeted: true } }];
}
return [{ json: { targeted: false } }];

const instant = value => {
  if (typeof value !== 'string' || !/T.*(?:Z|[+-]\d{2}:?\d{2})$/i.test(value) || !Number.isFinite(Date.parse(value))) throw new Error('REPORT_LEGACY_COVERAGE_REVIEW_REQUIRED');
  return new Date(Date.parse(value)).toISOString();
};
const bounds = row => {
  const g=row.stats?.report_generation;
  if (!g) throw new Error('REPORT_LEGACY_COVERAGE_REVIEW_REQUIRED');
  const start=instant(g.period_start),end=instant(g.period_end);
  if (start>=end || start.slice(0,10)!==row.period_start || end.slice(0,10)!==row.period_end) throw new Error('REPORT_PERIOD_METADATA_MISMATCH');
  return {start,end};
};
const sameScope = (row,c) => Number(row.client_id)===Number(c.client_id) && Number(row.platform_id)===Number(c.id) &&
  String(row.branch_id??'')===String(c.branch_id??'') && (row.report_scope===c.legacy_report_scope || row.report_scope===c.base_report_scope || String(row.report_scope||'').startsWith(c.base_report_scope+':window:'));
const query = values => values.map(([key,value]) => encodeURIComponent(key)+'='+encodeURIComponent(value)).join('&');

const context = $('Prepare Report Window').last().json;
if(context.coverage_complete)return [{json:{action:'skip'}}];
const saved = $input.all()[0]?.json || {};
const exists = Number.isSafeInteger(Number(saved.id)) && Number(saved.id) > 0;
if (exists && (Number(saved.client_id) !== Number(context.client_id) || Number(saved.platform_id) !== Number(context.id) ||
    String(saved.branch_id ?? '') !== String(context.branch_id ?? '') || ![context.report_scope, context.legacy_report_scope].includes(saved.report_scope) ||
    saved.report_type !== context.report_type)) throw new Error('REPORT_RESERVATION_SCOPE_MISMATCH');
if(exists){ const actual=bounds(saved); if(actual.start!==instant(context.period_start)||actual.end!==instant(context.period_end))throw new Error('REPORT_SAVED_COVERAGE_MISMATCH'); }
if (exists && saved.status === 'completed') return [{ json: { action: 'completed', saved_report: saved } }];
// No timeout-based takeover. A running or uncertain owner may still complete.
if (exists && saved.status !== 'failed') return [{ json: { action: 'skip' } }];
const previous = saved.stats?.report_generation;
const period = exists ? previous
  : { period_start: context.period_start, period_end: context.period_end };
if (!Number.isFinite(Date.parse(period.period_start)) || !Number.isFinite(Date.parse(period.period_end)) ||
    Date.parse(period.period_start) > Date.parse(period.period_end)) throw new Error('INVALID_RESERVED_REPORT_PERIOD');
if (exists && (period.period_start.slice(0,10) !== saved.period_start || period.period_end.slice(0,10) !== saved.period_end)) throw new Error('REPORT_PERIOD_METADATA_MISMATCH');
const owner = String($execution.id || '');
if (!owner) throw new Error('REPORT_EXECUTION_ID_MISSING');
const metadata = { version: 1, owner, period_start: period.period_start, period_end: period.period_end };
const scope = exists ? saved.report_scope : context.report_scope;
const identity = [['client_id','eq.'+context.client_id],['platform_id','eq.'+context.id],['report_type','eq.'+context.report_type],
  ['report_scope','eq.'+scope],['period_start','eq.'+period.period_start.slice(0,10)],['period_end','eq.'+period.period_end.slice(0,10)]];
const values = exists ? [['id','eq.'+saved.id],['client_id','eq.'+context.client_id],['status','eq.failed'],
  ['stats->report_generation->>owner', previous?.owner == null ? 'is.null' : 'eq.'+previous.owner]]
  : [['on_conflict','client_id,report_type,period_start,period_end,report_scope']];
const body = { status: 'processing', stats: { ...(exists ? saved.stats : {}), report_generation: metadata }, updated_at: new Date().toISOString() };
if (!exists) Object.assign(body, { client_id: context.client_id, branch_id: context.branch_id ?? null, platform_id: context.id,
  report_scope: scope, report_type: context.report_type, period_start: period.period_start.slice(0,10), period_end: period.period_end.slice(0,10), platforms: [context.platform_name] });
return [{ json: { action: 'claim', claim_method: exists ? 'PATCH' : 'POST', claim_url: "https://dhryldlprpdmsixhlaqe.supabase.co/rest/v1/reports"+'?'+query(values), claim_body: body,
  result_url: "https://dhryldlprpdmsixhlaqe.supabase.co/rest/v1/reports"+'?'+query([['select','*'], ...identity]) } }];

const instant = value => {
  if (typeof value !== 'string' || !/T.*(?:Z|[+-]\d{2}:?\d{2})$/i.test(value) || !Number.isFinite(Date.parse(value))) throw new Error('REPORT_LEGACY_COVERAGE_REVIEW_REQUIRED');
  return new Date(Date.parse(value)).toISOString();
};
const bounds = row => {
  const g=row.stats?.report_generation;
  if (!g) throw new Error('REPORT_LEGACY_COVERAGE_REVIEW_REQUIRED');
  const start=instant(g.period_start),end=instant(g.period_end);
  if (start>=end || start.slice(0,10)!==row.period_start || end.slice(0,10)!==row.period_end) throw new Error('REPORT_PERIOD_METADATA_MISMATCH');
  return {start,end};
};
const sameScope = (row,c) => Number(row.client_id)===Number(c.client_id) && Number(row.platform_id)===Number(c.id) &&
  String(row.branch_id??'')===String(c.branch_id??'') && (row.report_scope===c.legacy_report_scope || row.report_scope===c.base_report_scope || String(row.report_scope||'').startsWith(c.base_report_scope+':window:'));
const context = $('Prepare Report Window').last().json;
const report = $input.all()[0]?.json || {};
const generation = report.stats?.report_generation;
if (Number(report.client_id) !== Number(context.client_id) || Number(report.platform_id) !== Number(context.id) ||
    String(report.branch_id ?? '') !== String(context.branch_id ?? '') || generation?.owner !== String($execution.id) ||
    ![context.report_scope,context.legacy_report_scope].includes(report.report_scope)) throw new Error('REPORT_OWNER_MISMATCH');
const b=bounds(report); if(b.start!==instant(context.period_start)||b.end!==instant(context.period_end))throw new Error('REPORT_SAVED_COVERAGE_MISMATCH');
return [{ json: { ...context, report_scope: report.report_scope, period_start: generation.period_start, period_end: generation.period_end,
  report_id: report.id, report_generation: generation } }];

const instant = value => {
  if (typeof value !== 'string' || !/T.*(?:Z|[+-]\d{2}:?\d{2})$/i.test(value) || !Number.isFinite(Date.parse(value))) throw new Error('REPORT_LEGACY_COVERAGE_REVIEW_REQUIRED');
  return new Date(Date.parse(value)).toISOString();
};
const bounds = row => {
  const g=row.stats?.report_generation;
  if (!g) throw new Error('REPORT_LEGACY_COVERAGE_REVIEW_REQUIRED');
  const start=instant(g.period_start),end=instant(g.period_end);
  if (start>=end || start.slice(0,10)!==row.period_start || end.slice(0,10)!==row.period_end) throw new Error('REPORT_PERIOD_METADATA_MISMATCH');
  return {start,end};
};
const sameScope = (row,c) => Number(row.client_id)===Number(c.client_id) && Number(row.platform_id)===Number(c.id) &&
  String(row.branch_id??'')===String(c.branch_id??'') && (row.report_scope===c.legacy_report_scope || row.report_scope===c.base_report_scope || String(row.report_scope||'').startsWith(c.base_report_scope+':window:'));

const client=$('Determine Report Period').last().json;
let reviews=[];try{reviews=$('Loop Platform Reports').all(0);}catch{}
if(reviews.some(i=>Number(i.json.client_id)===Number(client.id)&&i.json.report_generation_review_required))throw new Error('REPORT_COVERAGE_REVIEW_REQUIRED');
const expected=$('Attach Report Context').all().map(i=>i.json).filter(p=>Number(p.client_id)===Number(client.id));
const rows=$input.all().map(i=>i.json).filter(r=>r.id!=null);
if(rows.length>=1000)throw new Error('REPORT_HISTORY_REVIEW_REQUIRED');
let failed=false;
const coverage=expected.map(p=>{
  const scoped=rows.filter(r=>sameScope(r,p));
  const known=scoped.map(row=>({row,...bounds(row)})).sort((a,b)=>a.start.localeCompare(b.start)||a.end.localeCompare(b.end));
  const complete=known.filter(h=>h.row.status==='completed');
  for(let i=1;i<complete.length;i++)if(complete[i].start<complete[i-1].end)throw new Error('REPORT_COVERAGE_OVERLAP_REVIEW_REQUIRED');
  failed ||= known.some(h=>h.row.status==='failed');
  const start=instant(p.period_start),end=instant(p.period_end);
  if(client.report_type==='initial_historical'){
    const found=complete.find(h=>h.row.report_type==='initial_historical'&&h.start===start&&h.end===end);
    return {ready:Boolean(found),end:found?.end};
  }
  let cursor=start;
  for(const h of complete){if(h.end<=cursor)continue;if(h.start>cursor)break;cursor=h.end;if(cursor>=end)break;}
  return {ready:cursor>=end,end:cursor};
});
const ready=coverage.length>0&&coverage.every(c=>c.ready);
// The client's watermark may only advance through coverage proven for every
// scope. In particular, a same-date report ending earlier is insufficient.
const end=ready ? (client.report_type==='initial_historical'
  ? new Date(Math.min(...coverage.map(c=>Date.parse(c.end)))).toISOString() : instant(client.period_end)) : null;
return [{json:{client_id:client.id,report_type:client.report_type,report_period_end:end,all_reports_ready:ready,report_generation_failed:!ready&&failed}}];

const instant = value => {
  if (typeof value !== 'string' || !/T.*(?:Z|[+-]\d{2}:?\d{2})$/i.test(value) || !Number.isFinite(Date.parse(value))) throw new Error('REPORT_LEGACY_COVERAGE_REVIEW_REQUIRED');
  return new Date(Date.parse(value)).toISOString();
};
const bounds = row => {
  const g=row.stats?.report_generation;
  if (!g) throw new Error('REPORT_LEGACY_COVERAGE_REVIEW_REQUIRED');
  const start=instant(g.period_start),end=instant(g.period_end);
  if (start>=end || start.slice(0,10)!==row.period_start || end.slice(0,10)!==row.period_end) throw new Error('REPORT_PERIOD_METADATA_MISMATCH');
  return {start,end};
};
const sameScope = (row,c) => Number(row.client_id)===Number(c.client_id) && Number(row.platform_id)===Number(c.id) &&
  String(row.branch_id??'')===String(c.branch_id??'') && (row.report_scope===c.legacy_report_scope || row.report_scope===c.base_report_scope || String(row.report_scope||'').startsWith(c.base_report_scope+':window:'));
const context = $('Prepare Report Window').last().json;
const plan = $('Evaluate Report Reservation').last().json;
const rows = $input.all().map(item => item.json).filter(row => row.id != null);
if (rows.length !== 1) throw new Error('REPORT_RESERVATION_NOT_CONFIRMED');
const report = rows[0];
